"use strict";

const BOC_RATES_URL = "https://www.bankofchina.com/sourcedb/whpj/";
const SNAPSHOT_URL = "https://raw.githubusercontent.com/AdenXie/Aden.github.io/exchange-rates/aud-cny.json";
const CACHE_SECONDS = 3 * 60 * 60;
const STALE_SECONDS = 7 * 24 * 60 * 60;

let lastSuccessfulQuote = null;

function validSnapshot(quote) {
  const age = Date.now() - Date.parse(quote?.fetchedAt);
  return quote?.currency === "AUD" && quote.quoteCurrency === "CNY" &&
    quote.officialUnit === "CNY per 100 AUD" && quote.source?.url === BOC_RATES_URL &&
    Number.isFinite(quote.spotBuy) && quote.spotBuy > 0 &&
    Number.isFinite(quote.spotSell) && quote.spotSell >= quote.spotBuy && quote.spotSell < 10000 &&
    /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(quote.publishedAt) &&
    age >= 0 && age < STALE_SECONDS * 1000 && quote.stale === false;
}

async function fetchSnapshot() {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 2000);
  try {
    // GitHub Raw may retain an older branch response for several minutes after
    // Actions writes a new snapshot. Each origin fetch should revalidate it.
    const response = await fetch(`${SNAPSHOT_URL}?t=${Date.now()}`, { signal: controller.signal });
    if (!response.ok) return null;
    const quote = await response.json();
    return validSnapshot(quote) ? quote : null;
  } catch (_) {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

function sendJson(response, statusCode, payload, cacheable = false) {
  response.statusCode = statusCode;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("X-Content-Type-Options", "nosniff");

  if (cacheable) {
    const freshSeconds = Math.max(0, Math.min(CACHE_SECONDS,
      Math.floor((Date.parse(payload.fetchedAt) + CACHE_SECONDS * 1000 - Date.now()) / 1000)));
    response.setHeader("Cache-Control", "public, max-age=0, must-revalidate");
    response.setHeader(
      "CDN-Cache-Control",
      `public, s-maxage=${freshSeconds}, stale-while-revalidate=60`
    );
    response.setHeader(
      "Vercel-CDN-Cache-Control",
      `public, s-maxage=${freshSeconds}, stale-while-revalidate=60`
    );
  } else {
    response.setHeader("Cache-Control", "private, no-store, max-age=0");
  }

  response.end(JSON.stringify(payload));
}

module.exports = async function audCnyQuote(request, response) {
  if (request.method && request.method !== "GET") {
    response.setHeader("Allow", "GET");
    sendJson(response, 405, { error: "method_not_allowed" });
    return;
  }

  // Vercel only reads the snapshot; bank access belongs to GitHub Actions.
  const snapshot = await fetchSnapshot();
  if (snapshot) lastSuccessfulQuote = snapshot;
  const quote = snapshot || lastSuccessfulQuote;
  if (quote && validSnapshot(quote)) {
    const fresh = Boolean(snapshot) &&
      Date.now() - Date.parse(quote.fetchedAt) < CACHE_SECONDS * 1000;
    sendJson(response, 200, fresh ? quote : {
      ...quote,
      stale: true,
      fetchError: snapshot ? "snapshot_stale" : "snapshot_unavailable"
    }, fresh);
    return;
  }
  console.warn("[aud-cny] No usable GitHub snapshot");
  sendJson(response, 502, { error: "snapshot_unavailable" });
};

module.exports.validSnapshot = validSnapshot;

'use strict';
const { createHash } = require('node:crypto');
const ENDPOINT = 'https://developer.amd.com.cn/radeon/api/v1/chat/completions';
const MAX_BODY = 96000, MAX_CONTEXT = 24000;
const REASONING_EFFORTS = new Set(['low', 'medium', 'xhigh']);
const apiKey = () => process.env.AI_API_KEY?.trim() || process.env.BIGMODEL_API_KEY?.trim();
const model = () => process.env.AI_MODEL?.trim();
// Best-effort per-instance protection; WAF is the cross-instance rate limiter.
// Only short-lived hashed IP counters are kept, never message content.
const buckets = new Map();
function allowed(ip) {
  const now = Date.now();
  for (const [key, value] of buckets) if (value.until <= now) buckets.delete(key);
  const key = createHash('sha256').update(ip).digest('hex');
  let bucket = buckets.get(key);
  if (!bucket) {
    if (buckets.size >= 2048) return false;
    buckets.set(key, bucket = { count: 0, until: now + 60000 });
  }
  return ++bucket.count <= 5;
}
function json(res, status, value) {
  res.statusCode = status;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.end(JSON.stringify(value));
}
function validate(body) {
  const messages = body?.messages;
  if (!Array.isArray(messages) || !messages.length || messages.length > 19 || messages.length % 2 !== 1) return null;
  let total = 0;
  for (let i = 0; i < messages.length; i++) {
    const m = messages[i];
    if (!m || m.role !== (i % 2 ? 'assistant' : 'user') || typeof m.content !== 'string' || !m.content.trim() || m.content.length > (i % 2 ? 16000 : 4000)) return null;
    total += m.content.length;
  }
  return total <= MAX_CONTEXT ? messages.map(({ role, content }) => ({ role, content })) : null;
}
async function bodyOf(req) {
  if (Number(req.headers['content-length']) > MAX_BODY) throw new Error('too_large');
  if (req.body !== undefined) {
    if (Buffer.byteLength(typeof req.body === 'string' ? req.body : JSON.stringify(req.body)) > MAX_BODY) throw new Error('too_large');
    return typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
  }
  const chunks = []; let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) throw new Error('too_large');
    chunks.push(chunk);
  }
  return JSON.parse(Buffer.concat(chunks).toString('utf8'));
}
async function handler(req, res) {
  res.setHeader('Cache-Control', 'no-store');
  res.setHeader('X-Content-Type-Options', 'nosniff');
  const configured = Boolean(apiKey() && model()) && process.env.CHAT_ENABLED !== 'false';
  if (req.method === 'GET') return json(res, 200, { available: configured, model: configured ? model() : null });
  if (req.method !== 'POST') { res.setHeader('Allow', 'GET, POST'); return json(res, 405, { error: 'method_not_allowed' }); }
  const host = req.headers.host;
  if (req.headers.origin && req.headers.origin !== `https://${host}` && !(process.env.NODE_ENV !== 'production' && req.headers.origin === `http://${host}`)) return json(res, 403, { error: 'forbidden' });
  if (!/^application\/json(?:;|$)/i.test(req.headers['content-type'] || '')) return json(res, 415, { error: 'invalid_request' });
  if (!configured) return json(res, 503, { error: 'not_configured' });
  let messages, reasoningEffort = 'low';
  try {
    const body = await bodyOf(req);
    messages = validate(body);
    if (body?.reasoningEffort !== undefined && !REASONING_EFFORTS.has(body.reasoningEffort)) return json(res, 400, { error: 'invalid_request' });
    reasoningEffort = body?.reasoningEffort || 'low';
  } catch { return json(res, 400, { error: 'invalid_request' }); }
  if (!messages) return json(res, 400, { error: 'invalid_request' });
  const ip = String(req.headers['x-vercel-forwarded-for'] || req.socket?.remoteAddress || 'unknown').split(',')[0].trim();
  if (!allowed(ip)) { res.setHeader('Retry-After', '60'); return json(res, 429, { error: 'rate_limited' }); }
  const controller = new AbortController();
  const abort = () => controller.abort();
  req.once('aborted', abort); res.once('close', abort);
  let timedOut = false;
  const timer = setTimeout(() => { timedOut = true; abort(); }, 60000);
  let reader;
  const emit = value => { if (!res.destroyed && !res.writableEnded) res.write(`data: ${JSON.stringify(value)}\n\n`); };
  try {
    const upstream = await fetch(ENDPOINT, {
      method: 'POST', signal: controller.signal,
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${apiKey()}` },
      body: JSON.stringify({ model: model(), messages: [{ role: 'system', content: 'You are a helpful assistant on Aden’s Space. Reply in the user’s language. You have no browsing tools or access to site articles. Be concise and honest about uncertainty.' }, ...messages], stream: true, reasoning_effort: reasoningEffort, max_tokens: 2048, temperature: 0.7 })
    });
    if (!upstream.ok) {
      const retryAfter = upstream.headers.get('retry-after');
      if (retryAfter) res.setHeader('Retry-After', retryAfter);
      await upstream.body?.cancel();
      return json(res, upstream.status === 429 ? 429 : 502, { error: upstream.status === 429 ? 'rate_limited' : [401,403].includes(upstream.status) ? 'provider_auth' : 'provider_unavailable' });
    }
    if (!upstream.body || !upstream.headers.get('content-type')?.includes('text/event-stream')) {
      await upstream.body?.cancel();
      return json(res, 502, { error: 'provider_unavailable' });
    }
    res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
    res.flushHeaders?.();
    reader = upstream.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '', finished = false, output = 0, lines = [];
    const event = () => {
      if (!lines.length) return;
      const data = lines.join('\n'); lines = [];
      if (data === '[DONE]') { finished = true; emit({ done: true }); return; }
      const payload = JSON.parse(data);
      if (payload.error) throw new Error('provider_error');
      const choice = payload.choices?.[0], text = choice?.delta?.content;
      if (typeof text === 'string') {
        output += text.length;
        if (output > 16000) throw new Error('output_limit');
        emit({ text });
      }
      if (choice?.finish_reason) {
        if (!['stop', 'length'].includes(choice.finish_reason)) throw new Error('provider_error');
        finished = true; emit({ done: true, truncated: choice.finish_reason === 'length' });
      }
    };
    while (!finished) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      if (buffer.length > 128000) throw new Error('invalid_stream');
      let index;
      while (!finished && (index = buffer.indexOf('\n')) >= 0) {
        const line = buffer.slice(0, index).replace(/\r$/, ''); buffer = buffer.slice(index + 1);
        if (!line) event(); else if (line.startsWith('data:')) lines.push(line.slice(5).trimStart());
      }
    }
    if (!finished) throw new Error('interrupted');
    res.end();
  } catch (cause) {
    if (res.destroyed || res.writableEnded) return;
    const code = cause?.cause?.code || cause?.code;
    const connectionTimeout = code === 'UND_ERR_CONNECT_TIMEOUT';
    // Log only an allowlisted failure code; never prompts, credentials or bodies.
    const safeCode = ['UND_ERR_CONNECT_TIMEOUT', 'ENOTFOUND', 'EAI_AGAIN', 'ECONNRESET', 'ECONNREFUSED', 'CERT_HAS_EXPIRED', 'UNABLE_TO_VERIFY_LEAF_SIGNATURE'].includes(code) ? code : 'UNKNOWN';
    const addresses = connectionTimeout ? [...new Set((cause?.cause?.message || '').match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) || [])] : [];
    console.warn(JSON.stringify({ event: 'chat_upstream_failure', phase: res.headersSent ? 'stream' : 'connect', code: safeCode, addresses }));
    const error = timedOut ? 'timeout' : res.headersSent ? 'interrupted' : connectionTimeout ? 'provider_connect_timeout' : 'provider_unavailable';
    if (res.headersSent) { emit({ error }); res.end(); }
    else json(res, timedOut ? 504 : 502, { error });
  } finally {
    clearTimeout(timer); req.removeListener('aborted', abort); res.removeListener('close', abort);
    abort(); await reader?.cancel().catch(() => {});
  }
}
module.exports = handler;
module.exports.validate = validate;

"use strict";

const FORECAST_ENDPOINT = "https://api.open-meteo.com/v1/forecast";
const CURRENT_FIELDS = [
  "temperature_2m",
  "apparent_temperature",
  "relative_humidity_2m",
  "weather_code",
  "wind_speed_10m",
  "is_day"
].join(",");

function readHeader(request, name) {
  const headers = request?.headers;
  if (!headers) return null;
  if (typeof headers.get === "function") return headers.get(name);
  const value = headers[name] ?? headers[name.toLowerCase()];
  return Array.isArray(value) ? value[0] : value ?? null;
}

function decodeHeader(value) {
  if (!value) return "";
  try {
    return decodeURIComponent(String(value).replace(/\+/g, "%20"));
  } catch (_) {
    return String(value);
  }
}

function sendJson(response, statusCode, payload) {
  response.statusCode = statusCode;
  response.setHeader("Content-Type", "application/json; charset=utf-8");
  response.setHeader("Cache-Control", "private, no-store, max-age=0");
  response.setHeader("X-Content-Type-Options", "nosniff");
  response.end(JSON.stringify(payload));
}

function isValidCoordinate(latitude, longitude) {
  return (
    Number.isFinite(latitude) &&
    Number.isFinite(longitude) &&
    latitude >= -90 &&
    latitude <= 90 &&
    longitude >= -180 &&
    longitude <= 180
  );
}

function parseCoordinate(value) {
  if (value === null || value === undefined || String(value).trim() === "") return Number.NaN;
  return Number(value);
}

module.exports = async function visitorWeather(request, response) {
  if (request.method && request.method !== "GET") {
    response.setHeader("Allow", "GET");
    sendJson(response, 405, { error: "method_not_allowed" });
    return;
  }

  const latitude = parseCoordinate(readHeader(request, "x-vercel-ip-latitude"));
  const longitude = parseCoordinate(readHeader(request, "x-vercel-ip-longitude"));

  if (!isValidCoordinate(latitude, longitude)) {
    sendJson(response, 503, { error: "location_unavailable" });
    return;
  }

  const city = decodeHeader(readHeader(request, "x-vercel-ip-city"));
  const region = decodeHeader(readHeader(request, "x-vercel-ip-country-region"));
  const country = decodeHeader(readHeader(request, "x-vercel-ip-country"));
  const label = city || region || country || "当前位置";

  const query = new URLSearchParams({
    latitude: latitude.toFixed(4),
    longitude: longitude.toFixed(4),
    current: CURRENT_FIELDS,
    daily: "sunrise,sunset",
    timezone: "auto",
    forecast_days: "1"
  });
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 7000);

  try {
    const weatherResponse = await fetch(`${FORECAST_ENDPOINT}?${query}`, {
      signal: controller.signal,
      headers: { Accept: "application/json" }
    });
    if (!weatherResponse.ok) throw new Error(`Open-Meteo returned ${weatherResponse.status}`);

    const forecast = await weatherResponse.json();
    if (!forecast?.current || !forecast?.timezone) throw new Error("Incomplete weather response");

    sendJson(response, 200, {
      location: {
        label,
        city,
        region,
        country,
        timezone: forecast.timezone,
        source: "vercel-ip",
        approximate: true
      },
      current: forecast.current,
      daily: forecast.daily
    });
  } catch (error) {
    sendJson(response, 502, {
      error: error?.name === "AbortError" ? "weather_timeout" : "weather_unavailable"
    });
  } finally {
    clearTimeout(timeout);
  }
};

.aden-language-switch{display:flex;align-items:center;gap:.35rem;white-space:nowrap;font-size:13px;margin-left:12px;flex-shrink:0}
.aden-language-switch a{color:inherit;opacity:.7;text-decoration:none}
.aden-language-switch a[aria-current="page"]{opacity:1;text-decoration:underline;text-underline-offset:4px}
.aden-translation-notice{font-size:.85rem;line-height:1.6;padding:12px 16px;border-left:2px solid var(--aden-signal,#a09525);background:var(--third-background-color);margin:16px 0}
html[lang="en"] .navbar-list{gap:12px}
@media(max-width:640px){.aden-language-switch{font-size:12px;margin-left:8px;gap:.2rem}.navbar-content .logo-title{min-width:0}}

/* Page-only styles; reuse the blog's fonts and light/dark palette. */
#aden-chat { color: var(--default-text-color); font-family: var(--aden-body-font); line-height: 1.65; }
#aden-chat [hidden] { display: none !important; }
#aden-chat .chat-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; margin-bottom: 1.4rem; }
#aden-chat .chat-label { color: var(--second-text-color); font: .65rem var(--aden-mono-font); letter-spacing: .09em; }
#aden-chat h2 { margin: .6rem 0 .35rem; padding: 0; border: 0; font: 600 clamp(1.5rem,4vw,2rem)/1.3 var(--aden-display-font); color: var(--first-text-color); }
#aden-chat h2::before, #aden-chat h2::after { display: none; }
#aden-chat .chat-heading p { margin: 0; color: var(--second-text-color); font-size: .85rem; }
#aden-chat button { border: 1px solid var(--border-color); border-radius: 9px; padding: .55rem .8rem; background: var(--background-color); color: var(--default-text-color); font: 500 .8rem var(--aden-body-font); cursor: pointer; white-space: nowrap; }
#aden-chat button:hover:not(:disabled) { border-color: var(--aden-cyan); }
#aden-chat button:disabled { opacity: .5; cursor: not-allowed; }
#aden-chat :is(button,textarea,.chat-transcript):focus-visible { outline: 2px solid var(--aden-cyan); outline-offset: 3px; }
#aden-chat .chat-transcript { height: clamp(260px,43dvh,520px); overflow-y: auto; overscroll-behavior: contain; padding: .5rem .6rem .5rem 0; scrollbar-width: thin; }
#aden-chat .chat-empty { min-height: 100%; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 1rem; box-sizing: border-box; }
#aden-chat .chat-spark { color: var(--aden-cyan); font-size: 3rem; line-height: 1; }
#aden-chat .chat-empty p { margin: 1rem 0 .4rem; font-size: 1.05rem; }
#aden-chat .chat-empty > span:last-child { color: var(--second-text-color); font-size: .8rem; max-width: 24rem; }
#aden-chat .chat-message { margin: .7rem 0 1.5rem; overflow-wrap: anywhere; min-width: 0; }
#aden-chat .chat-message[data-role="user"] { margin-left: 12%; padding: .85rem 1rem; background: var(--third-background-color); border-radius: 14px 14px 3px 14px; }
#aden-chat .chat-message[data-role="assistant"] { border-left: 2px solid var(--aden-cyan); padding: .2rem 0 .2rem 1rem; }
#aden-chat .chat-message-label { color: var(--second-text-color); font: .65rem var(--aden-mono-font); letter-spacing: .04em; }
#aden-chat .chat-message-progress { margin: .4rem 0; color: var(--aden-signal); font-size: .8rem; }
#aden-chat .chat-message-body { white-space: pre-wrap; font-size: .92rem; }
#aden-chat .chat-message-body p { margin: .5rem 0; }
#aden-chat .chat-message-body ul, #aden-chat .chat-message-body ol { padding-left: 1.4rem; margin: .5rem 0; }
#aden-chat .chat-message-body pre { white-space: pre; overflow-x: auto; max-width: 100%; padding: .8rem; background: var(--third-background-color); border-radius: 8px; }
#aden-chat .chat-message-body code { font-family: var(--aden-mono-font); font-size: .85em; }
#aden-chat .chat-message button { margin-top: .5rem; padding: .2rem .5rem; font-size: .7rem; }
#aden-chat .chat-composer { margin-top: 1rem; padding: .8rem 1rem; border: 1px solid var(--border-color); border-radius: 14px; background: var(--background-color); }
#aden-chat .chat-input-label { display: block; font-size: .75rem; color: var(--second-text-color); margin-bottom: .25rem; }
#aden-chat textarea { display: block; box-sizing: border-box; width: 100%; min-height: 78px; max-height: 200px; resize: vertical; border: 0; background: transparent; color: var(--first-text-color); font: 16px/1.6 var(--aden-body-font); padding: .3rem 0; }
#aden-chat textarea::placeholder { color: var(--second-text-color); }
#aden-chat .chat-reasoning-row { display: flex; align-items: center; justify-content: flex-end; gap: .55rem; color: var(--second-text-color); font-size: .68rem; }
#aden-chat .chat-reasoning { display: inline-flex; padding: 2px; border: 1px solid var(--border-color); border-radius: 9px; background: var(--third-background-color); }
#aden-chat .chat-reasoning button { border: 0; padding: .3rem .55rem; background: transparent; font: 600 .68rem var(--aden-mono-font); }
#aden-chat .chat-reasoning button[aria-checked="true"] { background: var(--aden-cyan); color: var(--background-color); }
#aden-chat .chat-composer-footer { display: flex; align-items: center; justify-content: space-between; gap: .5rem; margin-top: .5rem; }
#aden-chat .chat-composer-footer > div { display: flex; gap: .5rem; }
#aden-chat .chat-key-hint { font-size: .65rem; color: var(--second-text-color); }
#aden-chat [data-chat="send"] { background: var(--aden-cyan); border-color: var(--aden-cyan); color: var(--background-color); }
#aden-chat .chat-status { min-height: 1.5em; margin: .7rem 0 .35rem; font-size: .8rem; color: var(--second-text-color); }
#aden-chat .chat-status[data-error="true"] { color: var(--aden-signal); }
#aden-chat .chat-privacy { margin: 0; font-size: .7rem; color: var(--second-text-color); }
@media (max-width: 600px) {
  #aden-chat .chat-heading { flex-wrap: wrap; }
  #aden-chat .chat-heading button { padding: .4rem .6rem; }
  #aden-chat .chat-key-hint { display: none; }
  #aden-chat .chat-composer-footer { justify-content: flex-end; }
  #aden-chat .chat-message[data-role="user"] { margin-left: 5%; }
  #aden-chat .chat-transcript { height: 38dvh; min-height: 230px; }
}

/* Temporary chat: page memory only. No browser storage, cookies or analytics. */
(() => {
  'use strict';
  window.AdenSite.register('chat', '#aden-chat', (root, scope) => {
    const en = document.documentElement.lang.startsWith('en');
    const t = (zh, english) => en ? english : zh;
    const find = name => root.querySelector(`[data-chat="${name}"]`);
    const input = find('input'), form = find('form'), send = find('send'), stop = find('stop'), reasoning = find('reasoning');
    const transcript = find('messages'), empty = find('empty'), status = find('status');
    let history = [], active = null, available = false, reasoningEffort = 'low', assistantLabel = 'AI ASSISTANT';
    const errors = {
      not_configured: t('聊天暂未开放，请稍后再来。', 'Chat is not available yet. Please check back later.'),
      rate_limited: t('请求较多，请稍等一分钟再发送。', 'Too many requests. Wait a minute before sending again.'),
      provider_auth: t('聊天服务配置异常，请稍后再试。', 'Chat configuration needs attention. Please try again later.'),
      provider_unavailable: t('模型暂时无法响应，请稍后再试。', 'The model is unavailable. Please try again later.'),
      provider_connect_timeout: t('网站暂时无法连接模型服务，请稍后再试。', 'The site could not connect to the model service. Please try again later.'),
      timeout: t('等待超时，请稍后重试。', 'The request timed out. Please try again later.'),
      interrupted: t('连接中断，已收到的内容保留在下方。可重新发送问题。', 'Connection interrupted. Received text is kept below. You can send your question again.'),
      invalid_request: t('对话过长或消息格式有误，请清空后重新开始。', 'The conversation is too long or invalid. Clear it to start again.')
    };
    function setStatus(text, error = false) { status.textContent = text; status.dataset.error = String(error); }
    function controls() {
      send.disabled = !available || !!active || !input.value.trim();
      input.disabled = !available;
      stop.hidden = !active;
      input.readOnly = !!active;
      reasoning.querySelectorAll('button').forEach(button => { button.disabled = !available || !!active; });
      transcript.setAttribute('aria-busy', String(!!active));
    }
    function setReasoning(value) {
      if (!['low', 'medium', 'xhigh'].includes(value)) return;
      reasoningEffort = value;
      reasoning.querySelectorAll('[data-reasoning]').forEach(button => { button.setAttribute('aria-checked', String(button.dataset.reasoning === value)); });
    }
    function inline(node, text) {
      // A small safe subset: model HTML is always rendered as text.
      const regex = /(`[^`\n]+`|\*\*[^*\n]+\*\*)/g;
      let last = 0;
      for (const match of text.matchAll(regex)) {
        node.append(document.createTextNode(text.slice(last, match.index)));
        const code = match[0].startsWith('`'), el = document.createElement(code ? 'code' : 'strong');
        el.textContent = match[0].slice(code ? 1 : 2, code ? -1 : -2); node.append(el);
        last = match.index + match[0].length;
      }
      node.append(document.createTextNode(text.slice(last)));
    }
    function markdown(node, text) {
      node.replaceChildren();
      let code = null, list = null;
      for (const line of text.split('\n')) {
        if (/^\s*```/.test(line)) {
          list = null;
          if (code) code = null;
          else { const pre = document.createElement('pre'); code = document.createElement('code'); pre.append(code); node.append(pre); }
        } else if (code) code.append(document.createTextNode(line + '\n'));
        else {
          const item = line.match(/^\s*(?:([-*])|\d+[.)])\s+(.+)$/);
          if (item) {
            const tag = item[1] ? 'UL' : 'OL';
            if (!list || list.tagName !== tag) { list = document.createElement(tag); node.append(list); }
            const li = document.createElement('li'); inline(li, item[2]); list.append(li);
          } else {
            list = null;
            if (line.trim()) { const p = document.createElement('p'); inline(p, line.replace(/^#{1,6}\s+/, '')); node.append(p); }
          }
        }
      }
    }
    function message(role, text) {
      empty.hidden = true;
      const article = document.createElement('div'); article.className = 'chat-message'; article.dataset.role = role;
      const label = document.createElement('span'); label.className = 'chat-message-label';
      label.textContent = role === 'user' ? t('你', 'YOU') : assistantLabel;
      const body = document.createElement('div'); body.className = 'chat-message-body'; body.textContent = text;
      article.append(label, body); transcript.append(article);
      return { article, body };
    }
    function scroll() { transcript.scrollTop = transcript.scrollHeight; }
    async function submit(event) {
      event.preventDefault();
      if (active || !available || !input.value.trim()) return;
      const prompt = input.value.trim();
      if (history.length >= 20 || history.reduce((n, m) => n + m.content.length, prompt.length) > 24000) {
        setStatus(errors.invalid_request, true); return;
      }
      const controller = new AbortController(); active = controller;
      const timeout = setTimeout(() => { controller.timedOut = true; controller.abort(); }, 70000);
      message('user', prompt); const reply = message('assistant', '');
      const progress = document.createElement('div'); progress.className = 'chat-message-progress';
      progress.setAttribute('role', 'status');
      const requestReasoning = reasoningEffort;
      progress.textContent = requestReasoning === 'low' ? t('正在等待模型回答…', 'Waiting for the model…') : requestReasoning === 'medium' ? t('正在深入思考…', 'Thinking more deeply…') : t('正在进行最深入思考…', 'Using maximum reasoning…');
      reply.article.insertBefore(progress, reply.body);
      input.value = ''; controls(); scroll();
      setStatus(t('正在连接模型…', 'Connecting to the model…'));
      let answer = '', shown = 0, complete = false, truncated = false, reader, frame = null, drained = null;
      const update = () => {
        frame = null;
        if (active !== controller || scope.signal.aborted || controller.signal.aborted) { drained?.(); drained = null; return; }
        const atBottom = transcript.scrollHeight - transcript.scrollTop - transcript.clientHeight < 100;
        const remaining = answer.length - shown;
        if (remaining > 0) {
          shown = matchMedia('(prefers-reduced-motion: reduce)').matches ? answer.length : Math.min(answer.length, shown + (remaining > 180 ? Math.ceil(remaining / 60) : 2));
          reply.body.textContent = answer.slice(0, shown);
        }
        if (atBottom) scroll();
        if (shown < answer.length) frame = requestAnimationFrame(update);
        else { drained?.(); drained = null; }
      };
      const schedule = () => { if (frame === null) frame = requestAnimationFrame(update); };
      const finishTyping = () => shown >= answer.length ? Promise.resolve() : new Promise(resolve => { drained = resolve; schedule(); });
      try {
        const response = await fetch('/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ messages: [...history, { role: 'user', content: prompt }], reasoningEffort: requestReasoning }), signal: controller.signal, cache: 'no-store' });
        if (!response.ok) {
          const data = await response.json().catch(() => ({}));
          throw new Error(response.status === 429 ? 'rate_limited' : typeof data.error === 'string' ? data.error : 'provider_unavailable');
        }
        if (!response.body || !response.headers.get('content-type')?.includes('text/event-stream')) throw new Error('provider_unavailable');
        reader = response.body.getReader();
        const decoder = new TextDecoder(); let buffer = '';
        while (!complete) {
          const { value, done } = await reader.read();
          if (done) break;
          if (active !== controller || scope.signal.aborted) return;
          buffer += decoder.decode(value, { stream: true });
          if (buffer.length > 128000) throw new Error('interrupted');
          let index;
          while ((index = buffer.indexOf('\n\n')) >= 0) {
            const raw = buffer.slice(0, index); buffer = buffer.slice(index + 2);
            if (!raw.startsWith('data: ')) continue;
            const data = JSON.parse(raw.slice(6));
            if (data.error) throw new Error(data.error);
            if (typeof data.text === 'string') {
              answer += data.text;
              if (answer.length > 16000) throw new Error('interrupted');
              if (answer.trim()) progress.textContent = t('正在生成回答…', 'Writing the answer…');
              setStatus(progress.textContent);
              schedule();
            }
            if (data.done) {
              complete = true;
              truncated = Boolean(data.truncated);
              setStatus(data.truncated ? t('回答达到长度上限，可以继续追问。', 'Response length limit reached. You can ask a follow-up.') : t('可以继续追问，或清空开始新的对话。', 'Ask a follow-up, or clear this chat to start again.'));
              break;
            }
          }
        }
        if (!complete || !answer.trim()) throw new Error('interrupted');
        await finishTyping();
        if (controller.signal.aborted) throw new Error('interrupted');
        progress.textContent = truncated ? t('已达到回答长度上限', 'Response length limit reached') : t('回答已完成', 'Answer complete');
        reply.article.append(progress);
        history.push({ role: 'user', content: prompt }, { role: 'assistant', content: answer });
      } catch (error) {
        if (active !== controller || scope.signal.aborted) return;
        const stopped = controller.signal.aborted && !controller.timedOut;
        const text = stopped ? t('已停止。可重新发送问题。', 'Stopped. You can send your question again.') : errors[controller.timedOut ? 'timeout' : error.message] || errors.interrupted;
        setStatus(text, !stopped);
        progress.textContent = stopped ? t('已停止生成', 'Generation stopped') : text;
        progress.dataset.error = String(!stopped);
        reply.article.append(progress);
        input.value = prompt;
        if (!answer) reply.body.textContent = text;
      } finally {
        clearTimeout(timeout); if (frame !== null) cancelAnimationFrame(frame);
        await reader?.cancel().catch(() => {});
        if (active === controller && !scope.signal.aborted) {
          if (answer) {
            markdown(reply.body, answer);
            const copy = document.createElement('button'); copy.type = 'button'; copy.textContent = t('复制回答', 'Copy response');
            copy.addEventListener('click', async () => {
              try { await navigator.clipboard.writeText(answer); copy.textContent = t('已复制', 'Copied'); }
              catch { setStatus(t('无法自动复制，请选中文字复制。', 'Select the text to copy it manually.'), true); }
            }, { signal: scope.signal });
            reply.article.append(copy);
          }
          active = null; controls();
        }
      }
    }
    function reset() {
      const previous = active; active = null; previous?.abort(); history = [];
      transcript.querySelectorAll('.chat-message').forEach(el => el.remove());
      empty.hidden = false; input.value = ''; controls();
      setStatus(available ? t('对话仅在当前页面保留。', 'This conversation stays only on this page.') : errors.not_configured);
    }
    form.addEventListener('submit', submit, { signal: scope.signal });
    input.addEventListener('input', controls, { signal: scope.signal });
    reasoning.addEventListener('click', event => { const button = event.target.closest('[data-reasoning]'); if (button) setReasoning(button.dataset.reasoning); }, { signal: scope.signal });
    input.addEventListener('keydown', event => {
      if (event.key === 'Enter' && !event.shiftKey && !event.isComposing && !matchMedia('(pointer: coarse)').matches) { event.preventDefault(); form.requestSubmit(); }
    }, { signal: scope.signal });
    stop.addEventListener('click', () => active?.abort(), { signal: scope.signal });
    find('clear').addEventListener('click', () => { reset(); input.focus(); }, { signal: scope.signal });
    setReasoning('low');
    const check = new AbortController();
    const checkTimeout = setTimeout(() => check.abort(), 10000);
    scope.signal.addEventListener('abort', () => check.abort(), { once: true });
    fetch('/api/chat', { signal: check.signal, cache: 'no-store' }).then(async response => {
      if (!response.ok) throw new Error('unavailable');
      const data = await response.json();
      if (scope.signal.aborted) return;
      const configuredModel = typeof data.model === 'string' ? data.model.trim() : '';
      if (configuredModel) assistantLabel = configuredModel;
      available = data.available === true; controls();
      setStatus(available ? t('对话仅在当前页面保留。', 'This conversation stays only on this page.') : errors.not_configured);
    }).catch(() => {
      if (!scope.signal.aborted) { available = true; controls(); setStatus(t('服务状态暂不可用，可以尝试发送。', 'Service status unavailable. You can try sending a message.')); }
    }).finally(() => clearTimeout(checkTimeout));
    return () => { reset(); check.abort(); clearTimeout(checkTimeout); };
  });
})();

(() => {
  "use strict";

  const QUOTE_URL = "/api/aud-cny?v=4";
  const CACHE_KEY = "aden-aud-cny-v2";
  const CACHE_TTL = 3 * 60 * 60 * 1000;
  const FALLBACK_TTL = 30 * 24 * 60 * 60 * 1000;
  const REQUEST_TIMEOUT_MS = 15000;
  const RETRY_DELAY_MS = 1500;
  const ERROR_MESSAGES = {
    connection_timeout: "连接汇率服务超时",
    connection_failed: "无法连接汇率服务，请检查网络",
    source_timeout: "中行牌价源响应超时",
    source_unavailable: "中行牌价源读取失败",
    snapshot_unavailable: "汇率快照暂时无法读取",
    snapshot_stale: "汇率快照暂未更新",
    invalid_response: "汇率服务返回的数据异常",
    not_found: "汇率接口不存在（404）",
    access_denied: "汇率请求被拒绝",
    rate_limited: "汇率请求过于频繁，请稍后再试",
    service_unavailable: "汇率接口暂不可用"
  };

  function createCard() {
    const card = document.createElement("section");
    card.className = "cyber-exchange-card is-loading";
    card.id = "aud-cny-exchange-card";
    card.setAttribute("aria-label", "中国银行澳大利亚元兑人民币现汇牌价");
    card.innerHTML = `
      <div class="cyber-exchange-header">
        <span class="cyber-exchange-pair"><i aria-hidden="true"></i> AUD / CNY</span>
        <span>BANK OF CHINA // SPOT FX</span>
      </div>
      <div class="cyber-exchange-body" aria-live="polite">
        <div class="cyber-exchange-intro">
          <span class="cyber-data-label">FOREIGN EXCHANGE TAPE</span>
          <strong>澳元现汇牌价</strong>
          <span>人民币 / 100澳元</span>
        </div>
        <dl class="cyber-exchange-quotes">
          <div class="is-buy">
            <dt>现汇买入价 <span>BUY</span></dt>
            <dd data-exchange="buy">---.--</dd>
          </div>
          <div class="is-sell">
            <dt>现汇卖出价 <span>SELL</span></dt>
            <dd data-exchange="sell">---.--</dd>
          </div>
        </dl>
      </div>
      <div class="cyber-exchange-footer">
        <span data-exchange="status">正在连接中国银行牌价…</span>
        <a href="https://www.bankofchina.com/sourcedb/whpj/" target="_blank" rel="noopener noreferrer">数据来源于中国银行 ↗</a>
      </div>
      <p class="cyber-exchange-notice">现汇买入价与现汇卖出价均为中国银行每100澳元折合人民币的官方牌价。仅供个人非商业展示；实际交易以中国银行网上银行、手机银行、智能柜台或网点柜台价格为准。未经中国银行许可，不得用于商业转载。</p>`;
    return card;
  }

  function formatRate(value) {
    const number = Number(value);
    return Number.isFinite(number) ? `¥${number.toFixed(2)}` : "---.--";
  }

  function formatPublishedAt(value) {
    const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}:\d{2}):\d{2}$/);
    if (!match) return String(value || "时间未知");
    return `${match[1]}-${match[2]}-${match[3]} ${match[4]}`;
  }

  function isValidQuote(payload) {
    return (
      payload?.currency === "AUD" &&
      payload?.officialUnit === "CNY per 100 AUD" &&
      Number.isFinite(Number(payload.spotBuy)) &&
      Number.isFinite(Number(payload.spotSell)) &&
      Number(payload.spotBuy) >= 100 &&
      Number(payload.spotSell) >= 100 &&
      Boolean(payload.publishedAt)
    );
  }

  function renderQuote(card, payload, state = "live", error = null) {
    if (!card?.isConnected || !isValidQuote(payload)) return;
    card.querySelector('[data-exchange="buy"]').textContent = formatRate(payload.spotBuy);
    card.querySelector('[data-exchange="sell"]').textContent = formatRate(payload.spotSell);

    const updated = formatPublishedAt(payload.publishedAt);
    const status = card.querySelector('[data-exchange="status"]');
    if (state === "syncing") status.textContent = `正在同步最新快照 · 暂显示缓存牌价 · 中行更新 ${updated}`;
    else if (state === "stale" || payload.stale) status.textContent = `${errorMessage(error || { code: payload.fetchError || "source_unavailable" })} · 显示缓存牌价 · 中行更新 ${updated}`;
    else if (state === "cache") status.textContent = `缓存牌价 · 中行更新 ${updated}`;
    else status.textContent = `中行更新 ${updated} · 三小时缓存`;

    card.classList.remove("is-loading", "is-offline", "is-stale", "is-online");
    card.classList.add(state === "syncing" ? "is-loading" : state === "stale" || payload.stale ? "is-stale" : "is-online");
  }

  function readCachedQuote(allowExpired = false) {
    try {
      const cached = JSON.parse(localStorage.getItem(CACHE_KEY));
      if (!cached || !isValidQuote(cached.payload)) return null;
      if (!allowExpired && cached.payload.stale) return null;
      if (!allowExpired && cached.payload.fetchedAt && Date.now() - Date.parse(cached.payload.fetchedAt) >= CACHE_TTL) return null;
      const age = Date.now() - Number(cached.savedAt || 0);
      const limit = allowExpired ? FALLBACK_TTL : CACHE_TTL;
      return age >= 0 && age < limit ? cached.payload : null;
    } catch (_) {
      try { localStorage.removeItem(CACHE_KEY); } catch (_) { /* Storage is optional. */ }
      return null;
    }
  }

  function cacheQuote(payload) {
    try {
      localStorage.setItem(CACHE_KEY, JSON.stringify({ savedAt: Date.now(), payload }));
    } catch (_) {
      // The live card still works when local storage is unavailable.
    }
  }

  function quoteError(code) {
    return Object.assign(new Error(code), { code });
  }

  function errorMessage(error) {
    return ERROR_MESSAGES[error?.code] || ERROR_MESSAGES.service_unavailable;
  }

  function canRetry(error) {
    return ["connection_timeout", "connection_failed", "source_timeout", "source_unavailable", "snapshot_unavailable", "service_unavailable"].includes(error?.code);
  }

  async function fetchQuote(signal) {
    const controller = new AbortController();
    const cancel = () => controller.abort();
    if (signal?.aborted) { const error = new Error('Cancelled'); error.name = 'AbortError'; throw error; }
    signal?.addEventListener('abort', cancel, { once: true });
    const timeout = window.setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
    try {
      const response = await fetch(QUOTE_URL, {
        signal: controller.signal,
        headers: { Accept: "application/json" }
      });
      let payload;
      try {
        payload = await response.json();
      } catch (error) {
        if (error?.name === "AbortError") throw error;
        if (response.ok) throw quoteError("invalid_response");
      }
      if (!response.ok) {
        const statusCode = { 404: "not_found", 401: "access_denied", 403: "access_denied", 429: "rate_limited" }[response.status];
        const sourceCode = ["source_timeout", "source_unavailable", "snapshot_unavailable"].includes(payload?.error) ? payload.error : null;
        throw quoteError(statusCode || sourceCode || "service_unavailable");
      }
      if (!isValidQuote(payload)) throw quoteError("invalid_response");
      if (payload.fetchedAt && Date.now() - Date.parse(payload.fetchedAt) >= CACHE_TTL) payload.stale = true;
      return payload;
    } catch (error) {
      if (controller.signal.aborted || error?.name === "AbortError") throw quoteError("connection_timeout");
      throw error?.code ? error : quoteError("connection_failed");
    } finally {
      window.clearTimeout(timeout);
      signal?.removeEventListener('abort', cancel);
    }
  }

  async function loadQuote(card, signal) {
    const fresh = readCachedQuote(false);
    if (fresh) {
      renderQuote(card, fresh, "cache");
      return;
    }
    const previous = readCachedQuote(true);
    if (previous) renderQuote(card, previous, "syncing");

    if (signal?.aborted) return;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        const payload = await fetchQuote(signal);
        if (signal?.aborted || !card.isConnected) return;
        // Stale server fallbacks must not restart the browser's freshness clock.
        if (!payload.stale) cacheQuote(payload);
        renderQuote(card, payload, payload.stale ? "stale" : "live");
        return;
      } catch (error) {
        if (signal?.aborted || !card?.isConnected) return;
        if (attempt === 0 && canRetry(error)) {
          card.querySelector('[data-exchange="status"]').textContent = `${errorMessage(error)} · 正在重试（1/1）…`;
          await (window.AdenSite?.delay(RETRY_DELAY_MS, signal) || new Promise(resolve => window.setTimeout(resolve, RETRY_DELAY_MS)));
          if (signal?.aborted || !card.isConnected) return;
          continue;
        }
        if (previous) {
          renderQuote(card, previous, "stale", error);
        } else {
          card.querySelector('[data-exchange="status"]').textContent = `${errorMessage(error)} · 暂无可用缓存，请稍后刷新`;
          card.classList.remove("is-loading", "is-online", "is-stale");
          card.classList.add("is-offline");
        }
        return;
      }
    }
  }

  function mountExchangeCard(_root, scope) {
    const homeContent = document.querySelector(".home-content-container");
    if (!homeContent) return;

    let card = document.getElementById("aud-cny-exchange-card");
    if (!card) {
      card = createCard();
      const weatherCard = document.getElementById("visitor-status-hud");
      if (weatherCard) weatherCard.insertAdjacentElement("afterend", card);
      else homeContent.prepend(card);
    }
    const fresh = readCachedQuote(false);
    const cached = fresh || readCachedQuote(true);
    if (cached) renderQuote(card, cached, fresh ? "cache" : "syncing");
    scope.afterPaint(() => loadQuote(card, scope.signal));
  }

  window.AdenSite?.register('exchange', '.home-content-container', mountExchangeCard);
})();

(() => {
  "use strict";

  const VISITOR_WEATHER_URL = "/api/visitor-weather";
  const CACHE_KEY = "aden-visitor-weather-v2";
  const CACHE_TTL = 10 * 60 * 1000;
  const REQUEST_TIMEOUT_MS = 15000;
  const RETRY_DELAY_MS = 1500;
  const ERROR_MESSAGES = {
    connection_timeout: "连接天气服务超时",
    connection_failed: "无法连接天气服务，请检查网络",
    location_unavailable: "暂时无法识别 IP 所在地区",
    weather_timeout: "天气数据源响应超时",
    weather_unavailable: "天气数据源暂不可用",
    invalid_response: "天气服务返回的数据异常",
    not_found: "天气接口不存在（404）",
    access_denied: "天气请求被拒绝",
    rate_limited: "天气请求过于频繁，请稍后再试",
    service_unavailable: "天气接口暂不可用"
  };

  let activeTimeZone = getDeviceLocation().timezone;
  let timeFormatter = createTimeFormatter(activeTimeZone);
  let dateFormatter = createDateFormatter(activeTimeZone);

  const weatherCodes = {
    0: ["晴朗", "SUN", "☀"],
    1: ["大致晴朗", "CLEAR", "◒"],
    2: ["局部多云", "CLOUD", "◑"],
    3: ["阴天", "OVERCAST", "☁"],
    45: ["有雾", "FOG", "≋"],
    48: ["雾凇", "RIME", "≋"],
    51: ["小毛毛雨", "DRIZZLE", "⋰"],
    53: ["毛毛雨", "DRIZZLE", "⋰"],
    55: ["较强毛毛雨", "DRIZZLE", "⋰"],
    56: ["冻毛毛雨", "ICE RAIN", "❄"],
    57: ["较强冻毛毛雨", "ICE RAIN", "❄"],
    61: ["小雨", "RAIN", "⌁"],
    63: ["中雨", "RAIN", "⌁"],
    65: ["大雨", "HEAVY RAIN", "⌁"],
    66: ["冻雨", "ICE RAIN", "❄"],
    67: ["较强冻雨", "ICE RAIN", "❄"],
    71: ["小雪", "SNOW", "✦"],
    73: ["中雪", "SNOW", "✦"],
    75: ["大雪", "HEAVY SNOW", "✦"],
    77: ["米雪", "SNOW", "✦"],
    80: ["局部阵雨", "SHOWERS", "⌁"],
    81: ["阵雨", "SHOWERS", "⌁"],
    82: ["强阵雨", "SHOWERS", "⌁"],
    85: ["阵雪", "SNOW", "✦"],
    86: ["强阵雪", "SNOW", "✦"],
    95: ["雷暴", "STORM", "ϟ"],
    96: ["雷暴伴冰雹", "STORM", "ϟ"],
    99: ["强雷暴伴冰雹", "STORM", "ϟ"]
  };

  function createTimeFormatter(timeZone) {
    return new Intl.DateTimeFormat("en-AU", {
      timeZone,
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23"
    });
  }

  function createDateFormatter(timeZone) {
    return new Intl.DateTimeFormat("zh-CN", {
      timeZone,
      year: "numeric",
      month: "long",
      day: "numeric",
      weekday: "long"
    });
  }

  function isValidTimeZone(timeZone) {
    if (!timeZone) return false;
    try {
      new Intl.DateTimeFormat("en", { timeZone }).format();
      return true;
    } catch (_) {
      return false;
    }
  }

  function getTimeZoneName(timeZone) {
    try {
      const parts = new Intl.DateTimeFormat("en-AU", {
        timeZone,
        timeZoneName: "short"
      }).formatToParts(new Date());
      return parts.find((part) => part.type === "timeZoneName")?.value || timeZone;
    } catch (_) {
      return timeZone;
    }
  }

  function createCard() {
    const card = document.createElement("section");
    card.className = "cyber-weather-card";
    card.id = "visitor-status-hud";
    card.setAttribute("aria-label", "访客所在地时间与天气");
    card.innerHTML = `
      <div class="cyber-weather-header">
        <span class="cyber-weather-live"><i aria-hidden="true"></i> LIVE // <span data-location="name">LOCATING</span></span>
        <span class="cyber-weather-coords" data-location="timezone">LOCAL NODE</span>
      </div>
      <div class="cyber-weather-grid">
        <div class="cyber-clock-block">
          <span class="cyber-data-label" data-location="clock-label">LOCAL TIME / CALIBRATING</span>
          <time class="cyber-clock" datetime="">--:--:--</time>
          <span class="cyber-date">正在校准时间…</span>
        </div>
        <div class="cyber-current-weather" aria-live="polite">
          <span class="cyber-weather-icon" aria-hidden="true">◌</span>
          <div>
            <span class="cyber-temperature">--°</span>
            <span class="cyber-condition">正在识别访客地区…</span>
            <span class="cyber-feels-like">体感温度 --°C</span>
          </div>
        </div>
        <dl class="cyber-weather-metrics">
          <div><dt>HUMIDITY</dt><dd data-weather="humidity">--%</dd></div>
          <div><dt>WIND</dt><dd data-weather="wind">-- km/h</dd></div>
          <div><dt>SUNSET</dt><dd data-weather="sunset">--:--</dd></div>
        </dl>
      </div>
      <div class="cyber-weather-footer">
        <span data-weather="status">LOCATION LINK / CONNECTING</span>
        <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">DATA / OPEN-METEO</a>
      </div>`;
    return card;
  }

  function getDeviceLocation() {
    const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    return { label: "设备时间", timezone: isValidTimeZone(timezone) ? timezone : "UTC" };
  }

  function applyLocation(card, location = getDeviceLocation()) {
    const timeZone = isValidTimeZone(location.timezone) ? location.timezone : getDeviceLocation().timezone;
    const label = String(location.label || location.city || location.region || location.country || "当前位置");
    activeTimeZone = timeZone;
    timeFormatter = createTimeFormatter(activeTimeZone);
    dateFormatter = createDateFormatter(activeTimeZone);

    card.querySelector('[data-location="name"]').textContent = label.toLocaleUpperCase();
    card.querySelector('[data-location="timezone"]').textContent = timeZone;
    card.querySelector('[data-location="clock-label"]').textContent = `LOCAL TIME / ${getTimeZoneName(timeZone)}`;
    card.setAttribute("aria-label", `${label}时间与天气`);
  }

  function updateClock(card) {
    if (!card?.isConnected) return;
    const now = new Date();
    const clock = card.querySelector(".cyber-clock");
    const date = card.querySelector(".cyber-date");
    clock.textContent = timeFormatter.format(now);
    clock.dateTime = now.toISOString();
    date.textContent = dateFormatter.format(now);
  }

  function formatNumber(value, fractionDigits = 0) {
    const number = Number(value);
    return Number.isFinite(number) ? number.toFixed(fractionDigits) : "--";
  }

  function renderWeather(card, payload, source = "vercel") {
    if (!card?.isConnected || !payload?.current) return;
    applyLocation(card, payload.location);
    updateClock(card);

    const current = payload.current;
    const [condition, codeLabel, icon] = weatherCodes[current.weather_code] || ["天气未知", "UNKNOWN", "◇"];
    const sunsetValue = payload.daily?.sunset?.[0];
    const sunset = typeof sunsetValue === "string" ? sunsetValue.slice(11, 16) : "--:--";

    card.querySelector(".cyber-weather-icon").textContent = icon;
    card.querySelector(".cyber-temperature").textContent = `${formatNumber(current.temperature_2m)}°`;
    card.querySelector(".cyber-condition").textContent = `${condition} / ${codeLabel}`;
    card.querySelector(".cyber-feels-like").textContent = `体感温度 ${formatNumber(current.apparent_temperature)}°C`;
    card.querySelector('[data-weather="humidity"]').textContent = `${formatNumber(current.relative_humidity_2m)}%`;
    card.querySelector('[data-weather="wind"]').textContent = `${formatNumber(current.wind_speed_10m)} km/h`;
    card.querySelector('[data-weather="sunset"]').textContent = sunset;

    const status = card.querySelector('[data-weather="status"]');
    if (source === "cache") status.textContent = "LOCATION LINK / CACHED";
    else status.textContent = "LOCATION LINK / IP APPROX";
    card.classList.remove("is-offline");
    card.classList.add("is-online");
  }

  function isValidWeather(payload) {
    return Boolean(
      payload &&
      typeof payload.location === "object" &&
      payload.location !== null &&
      payload.location.source !== "fallback" &&
      typeof payload.location.timezone === "string" &&
      isValidTimeZone(payload.location.timezone) &&
      payload.current &&
      Number.isFinite(payload.current.temperature_2m) &&
      Number.isFinite(payload.current.weather_code)
    );
  }

  function clearCachedWeather() {
    try {
      sessionStorage.removeItem(CACHE_KEY);
    } catch (_) {
      // Storage may be blocked entirely, including removal. It is optional.
    }
  }

  function readCachedWeather() {
    try {
      const cached = JSON.parse(sessionStorage.getItem(CACHE_KEY));
      const age = Date.now() - cached?.savedAt;
      if (
        Number.isFinite(cached?.savedAt) &&
        age >= 0 &&
        age < CACHE_TTL &&
        isValidWeather(cached.payload)
      ) return cached.payload;
    } catch (_) {
      // Unreadable or malformed cache must not prevent a network request.
    }
    clearCachedWeather();
    return null;
  }

  function cacheWeather(payload) {
    try {
      sessionStorage.setItem(CACHE_KEY, JSON.stringify({ savedAt: Date.now(), payload }));
    } catch (_) {
      // The card still works when storage is unavailable.
    }
  }

  function weatherError(code) {
    return Object.assign(new Error(code), { code });
  }

  function errorMessage(error) {
    return ERROR_MESSAGES[error?.code] || ERROR_MESSAGES.service_unavailable;
  }

  function canRetry(error) {
    return ["connection_timeout", "connection_failed", "weather_timeout", "weather_unavailable", "service_unavailable"].includes(error?.code);
  }

  async function fetchJson(url, timeoutMs = REQUEST_TIMEOUT_MS, signal) {
    const controller = new AbortController();
    const cancel = () => controller.abort();
    if (signal?.aborted) { const error = new Error('Cancelled'); error.name = 'AbortError'; throw error; }
    signal?.addEventListener('abort', cancel, { once: true });
    const timeout = window.setTimeout(() => controller.abort(), timeoutMs);
    try {
      const response = await fetch(url, {
        signal: controller.signal,
        headers: { Accept: "application/json" }
      });
      let payload;
      try {
        payload = await response.json();
      } catch (error) {
        if (error?.name === "AbortError") throw error;
        if (response.ok) throw weatherError("invalid_response");
      }
      if (!response.ok) {
        const statusCode = { 404: "not_found", 401: "access_denied", 403: "access_denied", 429: "rate_limited" }[response.status];
        const sourceCode = ["location_unavailable", "weather_timeout", "weather_unavailable"].includes(payload?.error) ? payload.error : null;
        throw weatherError(statusCode || sourceCode || "service_unavailable");
      }
      return payload;
    } catch (error) {
      if (controller.signal.aborted || error?.name === "AbortError") throw weatherError("connection_timeout");
      throw error?.code ? error : weatherError("connection_failed");
    } finally {
      window.clearTimeout(timeout);
      signal?.removeEventListener('abort', cancel);
    }
  }

  async function loadWeather(card, signal) {
    try {
      const cached = readCachedWeather();
      if (cached) {
        renderWeather(card, cached, "cache");
        return;
      }
    } catch (_) {
      // A cached payload that cannot render must fall through to a fresh request.
      clearCachedWeather();
    }

    if (signal?.aborted) return;
    for (let attempt = 0; attempt < 2; attempt += 1) {
      try {
        const payload = await fetchJson(VISITOR_WEATHER_URL, REQUEST_TIMEOUT_MS, signal);
        if (!isValidWeather(payload)) throw weatherError("invalid_response");
        if (signal?.aborted || !card.isConnected) return;
        cacheWeather(payload);
        renderWeather(card, payload, "vercel");
        return;
      } catch (error) {
        if (signal?.aborted || !card?.isConnected) return;
        if (attempt === 0 && canRetry(error)) {
          card.querySelector(".cyber-condition").textContent = `${errorMessage(error)}，正在重试…`;
          card.querySelector('[data-weather="status"]').textContent = "LOCATION LINK / RETRY 1/1";
          await (window.AdenSite?.delay(RETRY_DELAY_MS, signal) || new Promise(resolve => window.setTimeout(resolve, RETRY_DELAY_MS)));
          if (signal?.aborted || !card.isConnected) return;
          continue;
        }
        applyLocation(card, getDeviceLocation());
        updateClock(card);
        card.querySelector(".cyber-temperature").textContent = "--°";
        card.querySelector(".cyber-weather-icon").textContent = "!";
        card.querySelector(".cyber-feels-like").textContent = "已保留设备时区 · 可稍后刷新重试";
        for (const [key, value] of [["humidity", "--%"], ["wind", "-- km/h"], ["sunset", "--:--"]]) {
          card.querySelector(`[data-weather="${key}"]`).textContent = value;
        }
        card.querySelector(".cyber-condition").textContent = errorMessage(error);
        card.querySelector('[data-weather="status"]').textContent = "LOCATION LINK / OFFLINE · 设备时间";
        card.classList.remove("is-online");
        card.classList.add("is-offline");
        return;
      }
    }
  }

  function mountWeatherCard(_root, scope) {
    const homeContent = document.querySelector(".home-content-container");
    if (!homeContent) return;

    let card = document.getElementById("visitor-status-hud");
    if (!card) {
      card = createCard();
      homeContent.prepend(card);
    }

    applyLocation(card, {
      ...getDeviceLocation(),
      label: "定位中",
    });
    updateClock(card);
    scope.clock(() => updateClock(card));
    const cached = readCachedWeather();
    if (cached) { try { renderWeather(card, cached, "cache"); } catch { clearCachedWeather(); } }
    scope.afterPaint(() => loadWeather(card, scope.signal));
  }

  window.AdenSite?.register('weather', '.home-content-container', mountWeatherCard);
})();

(() => {
  const root = document.documentElement;
  const storageKey = "REDEFINE-THEME-STATUS";

  try {
    const raw = window.localStorage.getItem(storageKey);
    let status = {};

    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed === "object") status = parsed;
    }

    if (typeof status.isDark !== "boolean") {
      status.isDark = true;
      window.localStorage.setItem(storageKey, JSON.stringify(status));
      root.classList.remove("light");
      root.classList.add("dark");
    }
  } catch (error) {
    root.classList.remove("light");
    root.classList.add("dark");
  }

  const syncColorScheme = () => {
    root.style.colorScheme = root.classList.contains("light") ? "light" : "dark";
  };

  syncColorScheme();

  if (!window.__adenThemeModeObserver) {
    window.__adenThemeModeObserver = new MutationObserver(syncColorScheme);
    window.__adenThemeModeObserver.observe(root, {
      attributes: true,
      attributeFilter: ["class"],
    });
  }

  document.addEventListener("DOMContentLoaded", syncColorScheme, { once: true });
})();

/* Shared lifecycle for site widgets. Loaded before page-specific scripts. */
(() => {
  'use strict';
  if (window.AdenSite) return;
  const widgets = new Map(), scripts = new Map();
  function afterPaint(callback, signal) {
    requestAnimationFrame(() => requestAnimationFrame(() => {
      if (signal.aborted) return;
      if (window.requestIdleCallback) requestIdleCallback(() => { if (!signal.aborted) callback(); }, { timeout: 1200 });
      else setTimeout(() => { if (!signal.aborted) callback(); }, 0);
    }));
  }
  function destroy(widget) {
    widget.controller?.abort();
    widget.cleanup?.();
    widget.root = null;
    widget.cleanup = null;
  }
  function mount(widget) {
    const root = document.querySelector(widget.selector);
    if (root && root === widget.root && !widget.controller.signal.aborted) return;
    destroy(widget);
    if (!root) return;
    widget.root = root;
    const controller = new AbortController();
    widget.controller = controller;
    const signal = controller.signal;
    widget.cleanup = widget.start(root, {
      signal,
      afterPaint: callback => afterPaint(callback, signal),
      clock(callback) {
        let timer;
        const refresh = () => { clearInterval(timer); timer = null; if (!document.hidden && !signal.aborted) { callback(); timer = setInterval(callback, 1000); } };
        document.addEventListener('visibilitychange', refresh, { signal });
        signal.addEventListener('abort', () => clearInterval(timer), { once: true });
        refresh();
      }
    });
  }
  const mountAll = () => widgets.forEach(mount);
  function register(name, selector, start) {
    if (widgets.has(name)) { mount(widgets.get(name)); return; }
    const widget = { selector, start };
    widgets.set(name, widget);
    if (document.readyState !== 'loading') mount(widget);
  }
  function delay(ms, signal) {
    return new Promise(resolve => {
      if (signal?.aborted) { resolve(); return; }
      const done = () => { clearTimeout(timer); signal?.removeEventListener('abort', done); resolve(); };
      const timer = setTimeout(done, ms);
      signal?.addEventListener('abort', done, { once: true });
    });
  }
  function loadScript(url) {
    if (scripts.has(url)) return scripts.get(url);
    const pending = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      const timeout = setTimeout(() => { script.remove(); scripts.delete(url); reject(new Error('Script timeout')); }, 15000);
      script.src = url; script.async = true;
      script.onload = () => { clearTimeout(timeout); resolve(); };
      script.onerror = () => { clearTimeout(timeout); script.remove(); scripts.delete(url); reject(new Error('Script unavailable')); };
      document.head.append(script);
    });
    scripts.set(url, pending);
    return pending;
  }
  window.AdenSite = { register, loadScript, delay };
  document.addEventListener('DOMContentLoaded', mountAll, { once: true });
  window.addEventListener('pageshow', mountAll);
  window.addEventListener('pagehide', () => widgets.forEach(destroy));
  let bound;
  const bind = swup => {
    if (!swup?.hooks || bound === swup) return;
    bound = swup;
    swup.hooks.before('content:replace', () => widgets.forEach(destroy));
    swup.hooks.on('page:view', mountAll);
  };
  bind(window.swup);
  window.addEventListener('redefine:swup:ready', event => bind(event.detail?.swup || window.swup));
  register('comments', '#twikoo-comment', (root, scope) => {
    let started = false;
    const start = async () => {
      if (started || scope.signal.aborted) return;
      started = true;
      try {
        await loadScript('/vendor/twikoo/twikoo.all.min.js');
        if (!scope.signal.aborted && root.isConnected) await window.twikoo.init({ el: '#twikoo-comment', envId: root.dataset.env, region: root.dataset.region || undefined, path: location.pathname });
      } catch {
        if (scope.signal.aborted) return;
        started = false;
        root.replaceChildren();
        const retry = document.createElement('button');
        retry.type = 'button';
        retry.textContent = document.documentElement.lang.startsWith('en') ? 'Retry loading comments' : '重新加载评论';
        retry.addEventListener('click', start, { signal: scope.signal });
        root.append(retry);
      }
    };
    if ('IntersectionObserver' in window) {
      const observer = new IntersectionObserver(entries => { if (entries.some(e => e.isIntersecting)) { observer.disconnect(); start(); } }, { rootMargin: '300px' });
      observer.observe(root);
      return () => observer.disconnect();
    }
    scope.afterPaint(start);
  });
})();
